+fn stored() -> Tool {
+    catalog().into_iter().find(|(n, _)| *n == TOOL).map(|(_, t)| t).expect("catalog entry")
+}
+
+fn pt(z: f64, r: f64) -> SpunPoint {
+    SpunPoint::line(z, r)
+}
+
+/// The tool drawn with a Ø8 neck from the flute top (22) to 30.
+fn necked() -> Vec<SpunPoint> {
