+            .neck
+            .iter()
+            .map(|b| HolderBand { r: b.r.max(beside(b.above, b.above + b.len)).min(sr), ..*b })
+            .collect();
+        if bands.iter().all(|b| b.r >= sr) { cylinder } else { bands }
+    }
